<script lang="ts">
  import { workflow, dateAfter } from '../lib/workflow';
  export let study:any; export let forecastScenarios:any[]; export let onSelectTab:(tab:string)=>void;
  $: completed=$workflow.actions.filter(a=>a.status==='Completed');
  $: reported=Math.min(study.delayDays,completed.reduce((n,a)=>n+(a.actualDays || 0),0));
  $: updatedDelay=Math.max(0,study.delayDays-reported);
  $: updatedDate=dateAfter(study.plannedDbl,updatedDelay);
</script>
<div class="space-y-6"><section class="panel"><p class="eyebrow">FORECAST AND FOLLOW-UP</p><h1 class="page-title">From action to outcome</h1><p class="page-intro">Compare illustrative scenarios and record what happened after the team acted.</p><div class="notice">Scenario dates and confidence ranges are illustrative, not statistically calibrated. Reported outcomes are manually entered; the demo does not train or recalibrate a model.</div></section>
<div class="scenario-grid"><div class="panel scenario-card"><small>PLANNED LOCK</small><strong>{study.plannedDbl}</strong><p>Original target</p></div><div class="panel scenario-card"><small>BASELINE FORECAST</small><strong>{study.forecastDbl}</strong><p>+{study.delayDays} days · example range {study.confidenceInterval}</p></div><div class="panel scenario-card highlight"><small>AFTER REPORTED OUTCOMES</small><strong>{updatedDate}</strong><p>{reported.toFixed(1)} days reported avoided · {completed.length} completed</p></div></div>
<section class="panel"><div class="section-heading"><div><p class="eyebrow">EXPLORE UNCERTAINTY</p><h2>Possible paths to lock</h2><p>Three fixed example scenarios and the assumptions behind them.</p></div></div><div class="forecast-list">{#each forecastScenarios as sc}<div><div class="forecast-name">{sc.scenario}</div><strong>{sc.forecastDate}</strong><p>{sc.assumptions}</p></div>{/each}</div><button class="text-link" on:click={() => onSelectTab('simulator')}>Build your own scenario →</button></section>
<section class="panel"><div class="section-heading"><div><p class="eyebrow">ACTION → OUTCOME</p><h2>What changed?</h2><p>Accepted actions can be marked complete with an observed outcome in the action plan.</p></div><button class="text-link" on:click={() => onSelectTab('action_workbench')}>Open action plan →</button></div>{#if completed.length}<div class="outcome-list">{#each completed as a}<div><div><strong>{a.title}</strong><p>{a.notes}</p><small>Owner: {a.owner} · Completed {a.completedAt}</small></div><span>Estimated {a.daysSaved} days<br/><b>Reported {a.actualDays} days</b></span></div>{/each}</div><p class="footnote">Reported values are added and capped at the baseline delay for demonstration. Overlapping effects may be double-counted.</p>{:else}<div class="empty-state">No completed actions yet. Accept an action, then record its completion and observed outcome to see it here.</div>{/if}</section>
<section class="panel"><p class="eyebrow">DEMO ACTIVITY</p><h2 class="minor-title">Decision history</h2>{#if $workflow.history.length}<div class="history-list">{#each $workflow.history as event}<div><time>{event.when}</time><span>{event.message}</span></div>{/each}</div>{:else}<p class="empty-state">Your decisions will appear here during this demo.</p>{/if}<p class="footnote">Browser-local demo history; not a regulated audit trail.</p></section></div>
